import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.*

const val MOD = 998244353

// ---------- Automaton ----------
class Automaton {
    // state 0 is root
    private val next = ArrayList<IntArray>()
    private val isTerm = ArrayList<Boolean>()
    private val out = ArrayList<Int>() // bitmask of terminal words ending here
    private var wordCount = 0

    init {
        addNode()
    }

    private fun addNode(): Int {
        next.add(IntArray(26) { -1 })
        isTerm.add(false)
        out.add(0)
        return next.size - 1
    }

    fun addWord(word: String, id: Int) {
        var u = 0
        for (ch in word) {
            val c = ch - 'a'
            if (next[u][c] == -1) {
                next[u][c] = addNode()
            }
            u = next[u][c]
        }
        isTerm[u] = true
        out[u] = out[u] or (1 shl id)
    }

    fun build() {
        val fail = IntArray(next.size) { 0 }
        val q = ArrayDeque<Int>()
        // init root transitions
        for (c in 0..25) {
            if (next[0][c] != -1) {
                fail[next[0][c]] = 0
                q.add(next[0][c])
            } else {
                next[0][c] = 0
            }
        }
        while (q.isNotEmpty()) {
            val u = q.removeFirst()
            // propagate output
            out[u] = out[u] or out[fail[u]]
            isTerm[u] = isTerm[u] || isTerm[fail[u]]
            for (c in 0..25) {
                val v = next[u][c]
                if (v != -1) {
                    fail[v] = next[fail[u]][c]
                    q.add(v)
                } else {
                    next[u][c] = next[fail[u]][c]
                }
            }
        }
    }

    fun size(): Int = next.size

    fun getNext(state: Int, c: Int): Int = next[state][c]

    fun isTerminal(state: Int): Boolean = isTerm[state]

    fun getOut(state: Int): Int = out[state]
}

// ---------- Matrix ----------
typealias Matrix = Array<IntArray>

fun matMul(A: Matrix, B: Matrix): Matrix {
    val n = A.size
    val C = Array(n) { IntArray(n) }
    for (i in 0 until n) {
        val Ai = A[i]
        val Ci = C[i]
        for (k in 0 until n) {
            val aik = Ai[k]
            if (aik != 0) {
                val Bk = B[k]
                for (j in 0 until n) {
                    Ci[j] = (Ci[j] + aik * Bk[j]) % MOD
                }
            }
        }
    }
    return C
}

fun matPow(var base: Matrix, var exp: Long): Matrix {
    val n = base.size
    var res = Array(n) { IntArray(n) }
    for (i in 0 until n) res[i][i] = 1
    while (exp > 0) {
        if (exp and 1L == 1L) res = matMul(res, base)
        base = matMul(base, base)
        exp = exp shr 1
    }
    return res
}

fun matVecMul(A: Matrix, v: IntArray): IntArray {
    val n = A.size
    val res = IntArray(n)
    for (i in 0 until n) {
        var sum = 0L
        val Ai = A[i]
        for (j in 0 until n) {
            sum += (Ai[j].toLong() * v[j]) % MOD
        }
        res[i] = (sum % MOD).toInt()
    }
    return res
}

// ---------- Main ----------
fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val (nStr, mStr) = br.readLine()!!.split(' ')
    val n = nStr.toInt()
    val m = mStr.toLong()

    val words = ArrayList<String>()
    for (i in 0 until n) {
        words.add(br.readLine()!!.trim())
    }

    // Build Aho-Corasick automaton
    val aut = Automaton()
    for (i in 0 until n) {
        aut.addWord(words[i], i)
    }
    aut.build()

    val S = aut.size() // states in single automaton
    val T = S * S      // combined states (u,v)

    // Map (u,v) -> id
    val id = Array(S) { IntArray(S) }
    var cnt = 0
    for (u in 0 until S) {
        for (v in 0 until S) {
            id[u][v] = cnt++
        }
    }

    // Build transition matrix T_size x T_size
    val mat = Array(T) { IntArray(T) }
    for (u in 0 until S) {
        for (v in 0 until S) {
            val from = id[u][v]
            for (c in 0..25) {
                val nu = aut.getNext(u, c)
                val nv = aut.getNext(v, c)
                val to = id[nu][nv]
                mat[from][to] = (mat[from][to] + 1) % MOD
            }
        }
    }

    // Initial vector: only (0,0) = 1
    val vec = IntArray(T)
    vec[id[0][0]] = 1

    // Exponentiate
    val matM = matPow(mat, m)
    val finalVec = matVecMul(matM, vec)

    // Sum over accepting states: both u and v terminal
    var ans = 0L
    for (u in 0 until S) {
        if (!aut.isTerminal(u)) continue
        for (v in 0 until S) {
            if (!aut.isTerminal(v)) continue
            ans = (ans + finalVec[id[u][v]]) % MOD
        }
    }

    println(ans)
}
